[patterns/application/micro-frontend/PTN-APP-MFE-009-shell-provided-props-pattern.md#step-1-define-shared-context-interface]

#### Step 1: Define Shared Context Interface

Create TypeScript interface defining shell-provided props:

```typescript
// packages/mfe-types/src/MfeContext.ts

export interface User {
  id: string;
  email: string;
  displayName: string;
  roles: string[];
  permissions: string[];
  stateCode?: string;  // Optional: state for state-specific staff
}

export interface AppConfig {
  apiBaseUrl: string;
  environment: 'development' | 'staging' | 'production';
  sessionTimeoutMinutes: number;
  version: string;
}

export interface FeatureFlags {
  claimsAutoAdjudication: boolean;
  eligibilityRealTimeVerification: boolean;
  providerDirectorySearch: boolean;
  [key: string]: boolean;  // Allow dynamic flags
}

export interface Theme {
  mode: 'light' | 'dark';
  primaryColor: string;
  fontFamily: string;
}

export interface MfeContext {
  user: User;
  config: AppConfig;
  featureFlags: FeatureFlags;
  theme: Theme;
  refreshToken?: () => Promise<void>;  // Optional: trigger token refresh
}

// Module mount function signature
export type MountFunction = (
  container: HTMLElement,
  context: MfeContext
) => Promise<() => void>;  // Returns unmount function
```

**Publish as NPM package:**
```json
// packages/mfe-types/package.json
{
  "name": "@gainwell/mfe-types",
  "version": "1.0.0",
  "main": "dist/index.js",
  "types": "dist/index.d.ts"
}
```

