[patterns/application/micro-frontend/PTN-APP-MFE-009-shell-provided-props-pattern.md#step-2-implement-shell-bootstrap]

#### Step 2: Implement Shell Bootstrap

Shell fetches all shared data during startup:

```typescript
// shell/src/bootstrap.tsx
import { MfeContext, User, AppConfig, FeatureFlags } from '@gainwell/mfe-types';
import { authService } from './services/authService';
import { configService } from './services/configService';

export async function bootstrapApplication(): Promise<MfeContext> {
  try {
    // Fetch all shared data in parallel
    const [user, config, featureFlags] = await Promise.all([
      authService.getCurrentUser(),
      configService.getAppConfig(),
      configService.getFeatureFlags(),
    ]);

    // Validate required data
    if (!user || !user.id) {
      throw new Error('Failed to authenticate user');
    }

    if (!config || !config.apiBaseUrl) {
      throw new Error('Failed to load application configuration');
    }

    // Create context object
    const context: MfeContext = {
      user,
      config,
      featureFlags,
      theme: {
        mode: user.preferences?.theme || 'light',
        primaryColor: '#0066cc',
        fontFamily: 'Inter, sans-serif',
      },
      refreshToken: async () => {
        await authService.refreshToken();
      },
    };

    // Store in shell state
    return context;
  } catch (error) {
    console.error('Application bootstrap failed:', error);
    throw error;
  }
}
```

**Shell Application:**

```typescript
// shell/src/App.tsx
import React, { useEffect, useState } from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import { MfeContext } from '@gainwell/mfe-types';
import { bootstrapApplication } from './bootstrap';
import { MicroFrontend } from './components/MicroFrontend';
import { ErrorBoundary } from './components/ErrorBoundary';

export function App() {
  const [context, setContext] = useState<MfeContext | null>(null);
  const [error, setError] = useState<Error | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function init() {
      try {
        const ctx = await bootstrapApplication();
        setContext(ctx);
      } catch (err) {
        setError(err as Error);
      } finally {
        setLoading(false);
      }
    }

    init();
  }, []);

  if (loading) {
    return <LoadingScreen message="Initializing application..." />;
  }

  if (error) {
    return (
      <ErrorScreen
        error={error}
        onRetry={() => window.location.reload()}
      />
    );
  }

  if (!context) {
    return <ErrorScreen error={new Error('Context not initialized')} />;
  }

  return (
    <ErrorBoundary>
      <BrowserRouter>
        <Header user={context.user} />
        <Routes>
          <Route
            path="/claims/*"
            element={<MicroFrontend name="claims" context={context} />}
          />
          <Route
            path="/provider/*"
            element={<MicroFrontend name="provider" context={context} />}
          />
          <Route
            path="/eligibility/*"
            element={<MicroFrontend name="eligibility" context={context} />}
          />
        </Routes>
        <Footer />
      </BrowserRouter>
    </ErrorBoundary>
  );
}
```

