#### Step 3: Implement Module Mount Function

Micro-frontends accept context via mount function:

```typescript
// claims-mfe/src/index.tsx
import React from 'react';
import ReactDOM from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';
import { MfeContext, MountFunction } from '@gainwell/mfe-types';
import { ClaimsApp } from './App';

// Export mount function following standard signature
export const mount: MountFunction = async (
  container: HTMLElement,
  context: MfeContext
) => {
  // Validate context at runtime
  if (!context.user || !context.config) {
    throw new Error('Invalid MfeContext: missing required properties');
  }

  console.log('[Claims MFE] Mounting with context:', {
    userId: context.user.id,
    environment: context.config.environment,
    featureFlags: Object.keys(context.featureFlags),
  });

  // Create React root and render
  const root = ReactDOM.createRoot(container);

  root.render(
    <React.StrictMode>
      <BrowserRouter>
        <ClaimsApp context={context} />
      </BrowserRouter>
    </React.StrictMode>
  );

  // Return unmount function
  return async () => {
    console.log('[Claims MFE] Unmounting');
    root.unmount();
  };
};

// For local development (standalone mode)
if (process.env.NODE_ENV === 'development' && !window.__POWERED_BY_QIANKUN__) {
  const mockContext: MfeContext = {
    user: {
      id: 'dev-user-123',
      email: 'developer@gainwell.com',
      displayName: 'Dev User',
      roles: ['State Staff'],
      permissions: ['claims.view', 'claims.submit'],
    },
    config: {
      apiBaseUrl: 'http://localhost:3001/api',
      environment: 'development',
      sessionTimeoutMinutes: 30,
      version: '1.0.0-dev',
    },
    featureFlags: {
      claimsAutoAdjudication: true,
      eligibilityRealTimeVerification: false,
      providerDirectorySearch: true,
    },
    theme: {
      mode: 'light',
      primaryColor: '#0066cc',
      fontFamily: 'Inter, sans-serif',
    },
  };

  mount(document.getElementById('root')!, mockContext);
}
```

**Claims App (uses props):**

```typescript
// claims-mfe/src/App.tsx
import React from 'react';
import { Routes, Route } from 'react-router-dom';
import { MfeContext } from '@gainwell/mfe-types';
import { ClaimsSearch } from './pages/ClaimsSearch';
import { ClaimDetail } from './pages/ClaimDetail';
import { ClaimSubmission } from './pages/ClaimSubmission';

interface ClaimsAppProps {
  context: MfeContext;
}

export function ClaimsApp({ context }: ClaimsAppProps) {
  const { user, config, featureFlags } = context;

  return (
    <div className="claims-app">
      <Routes>
        <Route
          path="/"
          element={
            <ClaimsSearch
