        />
        <Route
          path="/:claimId"
          element={<ClaimDetail apiBaseUrl={config.apiBaseUrl} />}
        />
        {user.permissions.includes('claims.submit') && (
          <Route
            path="/new"
            element={
              <ClaimSubmission
                apiBaseUrl={config.apiBaseUrl}
                autoAdjudicationEnabled={featureFlags.claimsAutoAdjudication}
              />
            }
          />
        )}
      </Routes>
    </div>
  );
}
```

