[patterns/application/micro-frontend/PTN-APP-MFE-009-shell-provided-props-pattern.md#step-4-handle-token-refresh]

#### Step 4: Handle Token Refresh

Shell handles authentication token refresh transparently:

```typescript
// shell/src/services/authService.ts
import { User } from '@gainwell/mfe-types';

class AuthService {
  private refreshTimer: NodeJS.Timeout | null = null;

  async getCurrentUser(): Promise<User> {
    const response = await fetch('/api/auth/user', {
      credentials: 'include',  // Include httpOnly cookies
    });

    if (!response.ok) {
      throw new Error('Failed to fetch user');
    }

    const user = await response.json();

    // Schedule token refresh (tokens expire in 60 minutes, refresh at 50 minutes)
    this.scheduleTokenRefresh(50 * 60 * 1000);

    return user;
  }

  async refreshToken(): Promise<void> {
    console.log('[AuthService] Refreshing token...');

    const response = await fetch('/api/auth/refresh', {
      method: 'POST',
      credentials: 'include',
    });

    if (!response.ok) {
      console.error('[AuthService] Token refresh failed, redirecting to login');
      window.location.href = '/login';
      return;
    }

    console.log('[AuthService] Token refreshed successfully');

    // Schedule next refresh
    this.scheduleTokenRefresh(50 * 60 * 1000);
  }

  private scheduleTokenRefresh(delayMs: number): void {
    if (this.refreshTimer) {
      clearTimeout(this.refreshTimer);
    }

    this.refreshTimer = setTimeout(async () => {
      await this.refreshToken();
    }, delayMs);
  }

  cleanup(): void {
    if (this.refreshTimer) {
      clearTimeout(this.refreshTimer);
    }
  }
}

export const authService = new AuthService();
```

**Modules receive refreshed tokens automatically** via httpOnly cookies; no module code changes required.

