[patterns/application/micro-frontend/PTN-APP-MFE-009-shell-provided-props-pattern.md#step-5-implement-runtime-validation]

#### Step 5: Implement Runtime Validation

Validate props at module boundary:

```typescript
// claims-mfe/src/validation/contextValidator.ts
import { MfeContext } from '@gainwell/mfe-types';
import { z } from 'zod';

const MfeContextSchema = z.object({
  user: z.object({
    id: z.string().min(1),
    email: z.string().email(),
    displayName: z.string().min(1),
    roles: z.array(z.string()),
    permissions: z.array(z.string()),
    stateCode: z.string().optional(),
  }),
  config: z.object({
    apiBaseUrl: z.string().url(),
    environment: z.enum(['development', 'staging', 'production']),
    sessionTimeoutMinutes: z.number().positive(),
    version: z.string(),
  }),
  featureFlags: z.record(z.string(), z.boolean()),
  theme: z.object({
    mode: z.enum(['light', 'dark']),
    primaryColor: z.string(),
    fontFamily: z.string(),
  }),
  refreshToken: z.function().optional(),
});

export function validateContext(context: unknown): MfeContext {
  try {
    return MfeContextSchema.parse(context);
  } catch (error) {
    console.error('[Claims MFE] Invalid context:', error);
    throw new Error(`Invalid MfeContext: ${error.message}`);
  }
}

// Use in mount function:
export const mount: MountFunction = async (container, context) => {
  const validatedContext = validateContext(context);
  // ... proceed with validated context
};
```

