[patterns/application/micro-frontend/PTN-APP-MFE-009-shell-provided-props-pattern.md#security-implementation-for-shell-provided-props]

#### Security Implementation for Shell-Provided Props

**Security Risk Assessment:**

| Risk | Severity | Mitigation |
|------|----------|------------|
| XSS via displayName | Medium | Sanitize with DOMPurify before rendering |
| Props tampering by malicious module | Low | Use `Object.freeze()` for immutability |
| Token exposure in props | High | NEVER include raw JWT tokens |
| Type confusion attacks | Medium | Runtime validation with Zod |

**1. Props Sanitization (XSS Prevention):**

```typescript
// shell/src/bootstrap.tsx
import DOMPurify from 'dompurify';
import { MfeContext } from '@gainwell/mfe-types';

export async function bootstrapApplication(): Promise<MfeContext> {
  const user = await authService.getCurrentUser();
  const config = await configService.getAppConfig();
  const featureFlags = await configService.getFeatureFlags();

  // Sanitize user-provided strings to prevent XSS
  const context: MfeContext = {
    user: {
      userId: user.id,
      email: user.email,
      // Sanitize displayName (could contain user-entered profile name)
      displayName: DOMPurify.sanitize(user.displayName, {
        ALLOWED_TAGS: [],      // No HTML tags allowed
        ALLOWED_ATTR: [],      // No attributes
        KEEP_CONTENT: true     // Keep text content only
      }),
      roles: user.roles,
      permissions: user.permissions,
    },
    config: {
      apiBaseUrl: config.apiBaseUrl,
      environment: config.environment,
      sessionTimeoutMinutes: config.sessionTimeoutMinutes,
    },
    featureFlags: featureFlags,
    theme: config.theme,
  };

  // Freeze context to prevent modification
  return Object.freeze(context);
}
```

**2. Runtime Validation in Modules:**

```typescript
// claims-mfe/src/index.tsx
import { z } from 'zod';
import { MfeContext, MountFunction } from '@gainwell/mfe-types';

// Define Zod schema for runtime validation
const MfeContextSchema = z.object({
  user: z.object({
    userId: z.string().uuid(),
    email: z.string().email(),
    displayName: z.string().min(1).max(100),
    roles: z.array(z.string()),
    permissions: z.array(z.string()),
  }),
  config: z.object({
    apiBaseUrl: z.string().url(),
    environment: z.enum(['development', 'staging', 'production']),
    sessionTimeoutMinutes: z.number().positive(),
  }),
  featureFlags: z.record(z.boolean()),
  theme: z.object({
    mode: z.enum(['light', 'dark']),
    primaryColor: z.string().regex(/^#[0-9A-Fa-f]{6}$/),
  }),
});

export const mount: MountFunction = async (
  container: HTMLElement,
  context: MfeContext
): Promise<() => void> => {
  try {
    // Validate context at module boundary
    const validatedContext = MfeContextSchema.parse(context);

    // Additional security: verify props are frozen
    if (!Object.isFrozen(context)) {
      console.warn('MfeContext not frozen—shell should freeze props');
    }

    // Mount module with validated context
    const root = ReactDOM.createRoot(container);
    root.render(
      <BrowserRouter>
        <ClaimsApp context={validatedContext} />
      </BrowserRouter>
    );

    return () => root.unmount();
  } catch (error) {
    if (error instanceof z.ZodError) {
      // Log validation error for security monitoring
      console.error('MfeContext validation failed:', error.errors);
      Sentry.captureException(error, {
        tags: { type: 'context_validation_failure' },
        extra: { errors: error.errors }
      });

      throw new Error('Invalid MfeContext provided by shell');
    }
    throw error;
  }
};
```

**3. Token Security (NEVER in Props):**

```typescript
// ❌ FORBIDDEN: Raw tokens in props
interface MfeContext {
  user: {
    userId: string;
    jwtToken: string;    // ❌ FORBIDDEN! Security vulnerability
  };
}

// ✅ SAFE: Shell handles tokens internally
interface MfeContext {
  user: {
    userId: string;      // ✅ User identity only
    email: string;       // ✅ No tokens
  };
  // Tokens stored in httpOnly cookies or shell-managed state
  // Modules call APIs without knowing about tokens
}

// shell/src/api/apiClient.ts
class ApiClient {
  private token: string | null = null;

  async fetch(endpoint: string, options: RequestInit = {}) {
    // Shell adds Authorization header transparently
    const headers = new Headers(options.headers);
    if (this.token) {
      headers.set('Authorization', `Bearer ${this.token}`);
    }

    return fetch(endpoint, { ...options, headers });
  }
}
```

**4. Props Immutability Enforcement:**

```typescript
// Enforce read-only at type level
export type ReadonlyMfeContext = Readonly<{
  user: Readonly<{
    userId: string;
    email: string;
    displayName: string;
    roles: ReadonlyArray<string>;
    permissions: ReadonlyArray<string>;
  }>;
  config: Readonly<{
    apiBaseUrl: string;
    environment: string;
    sessionTimeoutMinutes: number;
  }>;
  featureFlags: Readonly<Record<string, boolean>>;
  theme: Readonly<{
    mode: 'light' | 'dark';
    primaryColor: string;
  }>;
}>;

// Module mount signature
export type MountFunction = (
  container: HTMLElement,
  context: ReadonlyMfeContext  // Type enforces read-only
) => Promise<() => void>;
```

