[patterns/application/micro-frontend/PTN-APP-MFE-009-shell-provided-props-pattern.md#before-independent-api-calls-anti-pattern]

#### Before: Independent API Calls (Anti-Pattern)

**Shell Application (Before):**

```typescript
// shell/src/App.tsx (OLD - NO BOOTSTRAP)
export function App() {
  return (
    <BrowserRouter>
      <Header />
      <Routes>
        <Route path="/claims/*" element={<MicroFrontend name="claims" />} />
        <Route path="/provider/*" element={<MicroFrontend name="provider" />} />
        <Route path="/eligibility/*" element={<MicroFrontend name="eligibility" />} />
      </Routes>
    </BrowserRouter>
  );
}

// No context provided to modules
function MicroFrontend({ name }: { name: string }) {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const loadModule = async () => {
      const module = await import(`${name}/mount`);
      // No context passed to module
      await module.mount(containerRef.current!);
    };
    loadModule();
  }, [name]);

  return <div ref={containerRef} />;
}
```

**Claims Module (Before):**

```typescript
// claims-mfe/src/App.tsx (OLD - INDEPENDENT FETCHING)
export function ClaimsApp() {
  const [user, setUser] = useState(null);
  const [config, setConfig] = useState(null);
  const [featureFlags, setFeatureFlags] = useState({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function init() {
      // Each module independently fetches same data
      const [userData, configData, flagsData] = await Promise.all([
        fetch('/api/auth/user').then(r => r.json()),          // Redundant call #1
        fetch('/api/config/app').then(r => r.json()),         // Redundant call #2
        fetch('/api/config/feature-flags').then(r => r.json()), // Redundant call #3
      ]);

      setUser(userData);
      setConfig(configData);
      setFeatureFlags(flagsData);
      setLoading(false);
    }

    init();
  }, []);

  if (loading) return <LoadingSpinner />;

  return (
    <ClaimsSearch
      apiBaseUrl={config.apiBaseUrl}  // Hardcoded from config
      userId={user.id}
      permissions={user.permissions}
    />
  );
}
```

**Provider Module (Before):**

```typescript
// provider-mfe/src/App.tsx (OLD - SAME REDUNDANT FETCHING)
export function ProviderApp() {
  // Duplicate code: fetching same user, config, feature flags
  useEffect(() => {
    fetch('/api/auth/user').then(/* ... */);          // Redundant call #4
    fetch('/api/config/app').then(/* ... */);         // Redundant call #5
    fetch('/api/config/feature-flags').then(/* ... */); // Redundant call #6
  }, []);
  // ... rest of component
}
```

**Problems Observed:**

| Issue | Impact | Evidence |
|-------|--------|----------|
| **Redundant API Calls** | 6 API calls to fetch identical data (3 modules × 2 calls each) | Network tab shows 6 calls to `/api/auth/user`, `/api/config/*` |
| **Inconsistent State** | Modules receive different feature flag values if flags updated during loading | Module A gets `claimsAutoAdj: true`, Module B gets `claimsAutoAdj: false` |
| **Slow Initial Load** | Each module waits for 3 API calls (300-500ms) before rendering | Page load time: 2.1s (600ms per module × 3 modules, sequential) |
| **Duplicated Code** | 200+ lines of identical initialization code across 6 modules | Same `useEffect` logic in every module |
| **Session Timeout Drift** | Each module independently tracks session timeout, causing inconsistent behavior | User logged out in Claims module but still logged in Provider module |

**Metrics (Before):**
- **Total API Calls**: 6 calls (2 per module × 3 modules)
- **Average Page Load Time**: 2.1s (sequential module loading)
- **Bundle Size**: 200KB (duplicated fetching code across modules)
- **Developer Onboarding Time**: 4 hours (each module team implements own initialization)

